"""Minimal standard-library client for private text prompts to the Responses API.

Prompts are sent only in the HTTPS request and are not logged or saved by this
module. Requests set ``store`` to false; this does not change OpenAI's separate
data-retention policies. Set ``OPENAI_API_KEY`` in the environment, or pass a
key explicitly when creating a client.
"""

import json
import os
from typing import Optional
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(Exception):
    """An error returned by the API or encountered while making a request."""

    def __init__(self, message: str, status_code: Optional[int] = None):
        super().__init__(message)
        self.status_code = status_code


class OpenAIClient:
    """Send text prompts to OpenAI without third-party dependencies."""

    def __init__(
        self,
        api_key: Optional[str] = None,
        *,
        timeout: float = 60,
        base_url: str = "https://api.openai.com/v1",
    ):
        self.api_key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("Provide api_key or set the OPENAI_API_KEY environment variable")
        if timeout <= 0:
            raise ValueError("timeout must be greater than zero")
        self.timeout = timeout
        self.url = base_url.rstrip("/") + "/responses"

    def ask(self, prompt: str, *, model: str = DEFAULT_MODEL) -> str:
        """Return the assistant's text response to ``prompt``."""
        if not isinstance(prompt, str):
            raise TypeError("prompt must be a string")
        if not model:
            raise ValueError("model must not be empty")

        body = json.dumps({"model": model, "input": prompt, "store": False}).encode("utf-8")
        request = Request(
            self.url,
            data=body,
            headers={
                "Authorization": "Bearer " + self.api_key,
                "Content-Type": "application/json",
            },
            method="POST",
        )

        try:
            with urlopen(request, timeout=self.timeout) as response:
                response_body = response.read()
        except HTTPError as error:
            raise OpenAIError(
                "OpenAI API returned HTTP " + str(error.code), status_code=error.code
            ) from None
        except (URLError, TimeoutError, OSError) as error:
            raise OpenAIError("Could not reach the OpenAI API: " + str(error)) from None

        try:
            result = json.loads(response_body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            raise OpenAIError("OpenAI API returned an invalid JSON response") from None

        text = result.get("output_text")
        if isinstance(text, str):
            return text

        parts = []
        for item in result.get("output", []):
            if item.get("type") != "message":
                continue
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    parts.append(content.get("text", ""))
                elif content.get("type") == "refusal":
                    parts.append(content.get("refusal", ""))
        if parts:
            return "".join(parts)

        raise OpenAIError("OpenAI API response did not contain text output")


def ask(prompt: str, *, model: str = DEFAULT_MODEL, api_key: Optional[str] = None) -> str:
    """Send one prompt using ``OPENAI_API_KEY`` or the provided key."""
    return OpenAIClient(api_key=api_key).ask(prompt, model=model)
